export function splitTags(values) {
    return [...new Set(values.flatMap(value => String(value).split(/[\s,，]+/))
        .map(tag => tag.trim().toLowerCase()).filter(Boolean))]
}

export function isValidTag(tag) {
    return /^[\w\u4e00-\u9fa5\u3040-\u309f\u30a0-\u30ff\uac00-\ud7af-]+$/.test(tag)
}

// After # / -#, unprefixed words continue that tag group. Quoted text
// always remains a filename keyword, preserving mixed searches.
export function parseTagSearch(query) {
    if (!query.includes('#') && !query.includes('"')) {
        return { keywords: query.replace(/\s+/g, ' ').trim(), includeTags: [], excludeTags: [] }
    }
    const keywords = [], includeTags = [], excludeTags = []
    let group = null
    for (const token of query.match(/"[^"]*"|[^\s,，]+/g) || []) {
        if (token.startsWith('"') && token.endsWith('"')) {
            keywords.push(token.slice(1, -1))
            continue
        }
        let value = token
        if (token.startsWith('-#')) {
            group = excludeTags
            value = token.slice(2)
        } else if (token.startsWith('#')) {
            group = includeTags
            value = token.slice(1)
        }
        if (group && isValidTag(value)) group.push(value.toLowerCase())
        else if (value) keywords.push(value)
    }
    return {
        keywords: keywords.join(' ').trim(),
        includeTags: [...new Set(includeTags)],
        excludeTags: [...new Set(excludeTags)]
    }
}
